1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	
6	const BASE_PREMIUMS: Record<string, number> = {
7	  sword: 100,
8	  amulet: 60,
9	  staff: 80,
10	  potion: 40,
11	  rune: 25,
12	  moonstone: 25,
13	};
14	
15	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
16	// floating-point error that shifts the spec's round-up in MHPCO's favour.
17	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
18	
19	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
20	// round up, payouts (MHPCO pays) round down.
21	const roundPremiumInMHPCOsFavour = Math.ceil;
22	
23	export type ScenarioResult = { premium: number };
24	
25	type Item = { type: string };
26	
27	type Scenario = {
28	  steps: { items: Item[] }[];
29	};
30	
31	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
32	
33	const sumBasePremiums = (items: Item[]): number =>
34	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
35	
36	// Only recognises a block when the ENTIRE item list is one: no test yet covers
37	// a block alongside other items, so nothing drives grouping by component type.
38	const itemsFormASingleBlock = (items: Item[]): boolean =>
39	  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
40	
41	// A block is a discount on the components' combined base premium, not a flat
42	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
43	// 20 % stays visible as the rule it is.
44	const blockBasePremium = (items: Item[]): number => {
45	  const undiscounted = sumBasePremiums(items);
46	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
47	};
48	
49	const policyBasePremiumFor = (items: Item[]): number =>
50	  itemsFormASingleBlock(items) ? blockBasePremium(items) : sumBasePremiums(items);
51	
52	const quoteFor = (items: Item[]): ScenarioResult => {
53	  const policyBasePremium = policyBasePremiumFor(items);
54	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
55	  const premium = roundPremiumInMHPCOsFavour(
56	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
57	  );
58	  return { premium };
59	};
60	
61	// Every scenario so far holds exactly one quote step, so only the first is
62	// priced. The follow-up-contract discount test will drive priced-per-step.
63	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
64	  const [firstStep] = scenario.steps;
65	  return { results: [quoteFor(firstStep.items)] };
66	};
